import { UserFeedbackSchema } from "@myapp/shared/domains";
import { succeed } from "@myapp/shared/utils";

import { createUserFeedback } from "../../../data-access";
import { requireUserAndProfile } from "../context";
import { procedure, router } from "../trpc";

export const feedbackRouter = router({
    /**
     * Sends feedback from the app. `pageUrl` is where it was sent from; the
     * user agent is taken from the request. `id` is generated by the client.
     */
    submitFeedback: procedure
        .input(UserFeedbackSchema.pick({ id: true, category: true, message: true, pageUrl: true }))
        .mutation(async ({ ctx, input }) => {
            const { user } = await requireUserAndProfile(ctx);
            return succeed(await createUserFeedback({
                ...input,
                userId: user.id,
                userAgent: ctx.reqHeaders.get("user-agent")?.slice(0, 500) ?? null,
            }));
        }),
});
